const shell=document.createElement('header');shell.className='shellbar';shell.innerHTML='<span class="shellbrand">◈ 锦鲤云</span><span>数据监控</span><span class="selected">IAA 产品情报</span><span>项目管理</span><span class="right">设计评审版 · 示例数据　　◎</span>';document.body.prepend(shell);
const oldRender=render;let stateFilter='全部',regionFilter='全部地区',typeFilter='全部玩法',sortKey='rank',ascending=true,currentPage=1,pageSize=5,dense=false;let columns=JSON.parse(localStorage.getItem('yt-columns')||'[true,true,true,true]');let drawerId=null,drawerTab=0;
function toast(t){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2600)}
render=function(){oldRender();if(page===0){document.querySelector('.intro').textContent='持续积累市场表现，追溯入选依据，记录产品选用情况。';document.querySelector('.toolbar').outerHTML=`<div class="timeline"><span>① 每日榜单采集</span><span>——</span><span>② AI 识别与证据校验</span><span>——</span><span><b>③ 产品入库与挑选</b></span><span>——</span><span>④ 每周精选报告</span></div><div class="subtabs">${['全部','正式库','观察中','待识别'].map(x=>`<button class="${stateFilter===x?'on':''}" onclick="stateFilter='${x}';currentPage=1;render()">${x}${x==='待识别'?' · 0':''}</button>`).join('')}</div><div class="toolbar"><input aria-label="搜索产品" id="search" placeholder="产品名称 / 玩法关键词" oninput="q=this.value;currentPage=1;list()"><select aria-label="平台" id="platformFilter" onchange="filter=this.value;currentPage=1;list()">${['全部平台','微信','抖音','iOS 中国','Google Play'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><select aria-label="地区" onchange="regionFilter=this.value;currentPage=1;list()">${['全部地区','中国','美国','英国','德国','法国'].map(x=>`<option ${regionFilter===x?'selected':''}>${x}</option>`).join('')}</select><select aria-label="市场信号" onchange="kind=this.value;currentPage=1;list()">${['全部信号','快速上涨','持续表现','本周新发现'].map(x=>`<option ${kind===x?'selected':''}>${x}</option>`).join('')}</select><button class="primary" onclick="list();toast('已按当前条件筛选')">查询</button><button class="secondary" onclick="resetFilters()">重置</button></div><div class="resultbar"><span id="resultCount"></span><div><button class="link" onclick="dense=!dense;list()">${dense?'标准行高':'紧凑行高'}</button><button class="link" onclick="columnMenu()">列设置 ⚙</button><button class="link" onclick="exportProducts()">导出筛选结果 ↓</button></div></div><div id="list"></div><div id="pagination"></div>`;document.getElementById('search').value=q;list()}document.querySelector('aside>div:last-child').style.fontSize='11px'};
function filtered(){return games.filter(g=>(filter==='全部平台'||g.platform.includes(filter))&&(regionFilter==='全部地区'||(regionFilter==='中国'?['微信','抖音','iOS 中国'].includes(g.platform):g.platform.includes(regionFilter)))&&(kind==='全部信号'||g.signal===kind)&&(stateFilter==='全部'||(stateFilter==='正式库'&&g.formal)||(stateFilter==='观察中'&&!g.formal))&&(!q||(g.name+g.type).toLowerCase().includes(q.toLowerCase()))).sort((a,b)=>(ascending?1:-1)*(a[sortKey]-b[sortKey]))}
list=function(){if(!document.getElementById('resultCount'))return;let a=filtered(),start=(currentPage-1)*pageSize;document.getElementById('resultCount').textContent=`共 ${a.length} 款产品　 ·　数据日期：2026-10-25（示例）`;document.getElementById('list').className='tablewrap'+(dense?' compact':'');document.getElementById('list').innerHTML=`<table><thead><tr><th>产品名称 / 核心玩法</th><th>平台 / 地区</th><th>入库状态</th>${columns[0]?'<th><button onclick="sortBy(\'rank\')">热度排名 ↕</button></th>':''}${columns[1]?'<th><button onclick="sortBy(\'up\')">7日变化 ↕</button></th>':''}${columns[2]?'<th>市场信号 / 入选依据</th>':''}${columns[3]?'<th>选用情况</th>':''}<th>操作</th></tr></thead><tbody>${a.slice(start,start+pageSize).map(g=>`<tr><td><div class="productcell"><span class="miniicon" style="background:${g.bg}">${g.icon}</span><div><button class="link" onclick="show(${g.id})">${g.name}</button><div class="muted">${g.type}</div></div></div></td><td>${g.platform}</td><td><span class="statuspill ${g.formal?'':'observe'}">${g.formal?'正式库':'观察中'}</span></td>${columns[0]?`<td>#${g.rank}</td>`:''}${columns[1]?`<td class="green">${g.up?'↑ '+g.up:'—'}</td>`:''}${columns[2]?`<td>${g.signal}<div class="muted" style="margin-top:5px">${g.reason}</div></td>`:''}${columns[3]?`<td>${records.filter(r=>r.id===g.id).length} 人选用<div class="muted">${records.filter(r=>r.id===g.id&&r.status==='制作中').length} 制作中</div></td>`:''}<td><button class="link" onclick="show(${g.id})">详情</button><button class="link" onclick="pick(${g.id})">选用</button></td></tr>`).join('')}</tbody></table>${!a.length?'<div class="empty">暂无匹配产品<p>尝试减少筛选条件，或重置后重新查找。</p><button class="secondary" onclick="resetFilters()">清空筛选</button></div>':''}`;document.getElementById('pagination').innerHTML=`<div class="pager"><span class="muted">支持同一产品多人选用，所有数据为原型示例</span><div><select aria-label="每页数量" onchange="pageSize=Number(this.value);currentPage=1;list()">${[5,10,20].map(n=>`<option ${n===pageSize?'selected':''} value="${n}">${n} 条 / 页</option>`).join('')}</select> <button ${currentPage===1?'disabled':''} onclick="currentPage--;list()">上一页</button>　${currentPage} / ${Math.max(1,Math.ceil(a.length/pageSize))}　<button ${start+pageSize>=a.length?'disabled':''} onclick="currentPage++;list()">下一页</button></div></div>`};function sortBy(k){ascending=k===sortKey?!ascending:true;sortKey=k;list()}function resetFilters(){q='';filter='全部平台';kind='全部信号';regionFilter='全部地区';stateFilter='全部';currentPage=1;render()}
function columnMenu(){let e=document.querySelector('.popover');if(e){e.remove();return}e=document.createElement('div');e.className='popover';e.innerHTML='<b>显示字段</b>'+['热度排名','7日变化','市场依据','选用情况'].map((s,i)=>`<label><input type="checkbox" ${columns[i]?'checked':''} onchange="columns[${i}]=this.checked;localStorage.setItem('yt-columns',JSON.stringify(columns));list()">${s}</label>`).join('')+'<button class="link" onclick="this.parentElement.remove()">完成</button>';document.querySelector('.resultbar').after(e)}
show=function(id){drawerId=id;drawerTab=0;draw()};function closeDrawer(){document.querySelector('.veil')?.remove();document.querySelector('.drawer')?.remove();drawerId=null}function draw(){document.querySelector('.veil')?.remove();document.querySelector('.drawer')?.remove();let g=games[drawerId];let v=document.createElement('div');v.className='veil';v.onclick=closeDrawer;document.body.append(v);let d=document.createElement('section');d.className='drawer';d.setAttribute('role','dialog');d.setAttribute('aria-label','产品详情');d.innerHTML=`<button class="secondary close" onclick="closeDrawer()">关闭 ×</button><div class="gamehead"><span class="icon" style="--bg:${g.bg}">${g.icon}</span><div><h2>${g.name}</h2><span class="muted">${g.platform} · ${g.type}</span></div></div><div class="detailmeta"><span class="statuspill">${g.formal?'正式库':'观察中'}</span><span class="tag">${g.signal}</span><span class="tag">虚构示例 · 非市场事实</span></div><div class="subtabs">${['产品概览','榜单历史','入库依据','选用记录'].map((s,i)=>`<button class="${i===drawerTab?'on':''}" onclick="drawerTab=${i};draw()">${s}</button>`).join('')}</div><div id="drawerContent"></div><div style="margin-top:20px"><button class="primary" onclick="pick(${g.id})">＋ 新增选用记录</button></div>`;document.body.append(d);let content='';if(drawerTab===0)content=`<h2>核心玩法</h2><p style="line-height:1.9">${g.desc}</p><span class="tag">${g.type}</span><div class="panel"><h3>截图与视频</h3><div class="empty" style="padding:30px;background:#f6f8fb;margin-top:15px">暂无授权素材<p>接入真实数据后展示截图和原始视频入口</p></div></div><div class="two"><div class="panel">首次发现<p>2026-10-19（示例）</p></div><div class="panel">实际上线时间<p>未知</p></div></div>`;if(drawerTab===1)content=`<p class="notice">仅展示同一平台和同一热度榜的历史。采集失败不作为掉榜。</p><svg class="trend" viewBox="0 0 600 170"><path d="M40 20V140H570" stroke="#dce4ee" fill="none"/><path d="M40 125L300 80L560 30" stroke="#168bff" stroke-width="3" fill="none"/><g fill="#168bff"><circle cx="40" cy="125" r="5"/><circle cx="300" cy="80" r="5"/><circle cx="560" cy="30" r="5"/></g><g font-size="12" fill="#71829a"><text x="25" y="163">10-19</text><text x="280" y="163">10-22</text><text x="535" y="163">10-25</text><text x="535" y="20">#${g.rank}</text></g></svg><table><tr><th>日期</th><th>名次</th><th>榜单</th></tr>${[2,1,0].map(n=>`<tr><td>2026-10-${25-n*3}</td><td>#${g.rank+n*Math.round(g.up/2)}</td><td>模拟热度榜 · ${g.platform}</td></tr>`).join('')}</table>`;if(drawerTab===2)content=`<h2>市场表现依据</h2><div class="evidence">${g.reason}<br>榜单来源：原型模拟榜单<br>证据时间：2026-10-25（示例）</div><h2>纯 IAA 判断</h2><div class="notice">本原型不构成真实 IAA 判断。正式系统须保存证据来源、提取内容、确认时间；证据不足进入待识别区。</div><h2>规则命中记录</h2><table><tr><th>判断项</th><th>结果</th></tr><tr><td>市场信号</td><td>${g.signal}</td></tr><tr><td>当前归属</td><td>${g.formal?'正式库（模拟）':'观察中（模拟）'}</td></tr></table>`;if(drawerTab===3)content='<h2>选用记录</h2><p class="muted">每人独立填报，可编辑负责人、状态、时间和备注。</p>'+recordTable(records.filter(r=>r.id===g.id));document.getElementById('drawerContent').innerHTML=content}
recordTable=function(rs){return rs.length?`<div class="tablewrap"><table><tr><th>产品 / 负责人</th><th>状态</th><th>选用日期</th><th>备注</th><th>操作</th></tr>${rs.map(r=>`<tr><td>${games[r.id].name}<br><span class="muted">${esc(r.owner)}</span></td><td><span class="statuspill">${r.status}</span></td><td>${r.date}</td><td>${esc(r.note)||'—'}</td><td><button class="link" onclick="editRecord('${r.key}')">编辑记录</button></td></tr>`).join('')}</table></div>`:'<div class="empty">尚未有人选用<p>点击“新增选用记录”填写负责人即可。</p></div>'};
function editRecord(key){let r=records.find(r=>r.key===key),d=document.getElementById('claim');d.innerHTML=`<button class="secondary close" onclick="this.closest('dialog').close()">关闭</button><h2>编辑选用记录</h2><form onsubmit="saveRecord(event,'${key}')"><label>负责人</label><input name="owner" value="${esc(r.owner)}" required maxlength="40"><label>制作状态</label><select name="status">${['已选','制作中','已完成','放弃'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select><div class="two">${[['date','选用日期'],['started','开始日期'],['finished','完成日期']].map(([n,s])=>`<div><label>${s}</label><input type="date" name="${n}" value="${r[n]||''}" ${n==='date'?'required':''}></div>`).join('')}</div><label>备注</label><textarea name="note" style="width:100%" rows="3">${esc(r.note)}</textarea><p><button class="primary">保存修改</button></p></form>`;d.showModal()}function saveRecord(e,key){e.preventDefault();let a=Object.fromEntries(new FormData(e.target));if(a.started&&a.finished&&a.finished<a.started){toast('完成日期不能早于开始日期');return}Object.assign(records.find(r=>r.key===key),a);save();document.getElementById('claim').close();render();if(drawerId!==null)draw();toast('选用记录已更新')}
const oldAdd=add;add=function(e,id){oldAdd(e,id);if(drawerId!==null){drawerTab=3;draw()}toast('已添加选用记录，可继续添加其他负责人')};function exportProducts(){let data='产品,平台,类型,状态,排名,信号\n'+filtered().map(g=>[g.name,g.platform,g.type,g.formal?'正式库':'观察中',g.rank,g.signal].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');let u=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download='产品库-示例.csv';a.click();URL.revokeObjectURL(u);toast('已导出当前筛选结果')};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]'))closeDrawer()});render();
